9	// TestPolicyFieldsCoverStruct guards the single policy field table against
10	// the exact drift this table exists to prevent: a Policy struct field that no
11	// table entry reaches (it would silently miss the fingerprint, the UTF-8
12	// decision and the archive), or a table entry that reads the same member as
13	// another. Each struct field is stamped with a unique sentinel, after which
14	// every table accessor must resolve to exactly one distinct field, and its
15	// kind must match the field's type.
16	func TestPolicyFieldsCoverStruct(t *testing.T) {
17		tp := reflect.TypeOf(Policy{})
18		var p Policy
19		pv := reflect.ValueOf(&p).Elem()
20		sentinels := make(map[string]string, tp.NumField())
21		boolFields := make(map[string]bool)
22		for i := 0; i < tp.NumField(); i++ {
23			sf := tp.Field(i)
24			switch sf.Type.Kind() {
25			case reflect.String:
26				v := fmt.Sprintf("\x00policy-field-%d\x00", i)
27				pv.Field(i).SetString(v)
28				sentinels[sf.Name] = v
29			case reflect.Bool:
30				pv.Field(i).SetBool(true)
31				boolFields[sf.Name] = true
32			default:
33				t.Fatalf("Policy.%s has unhandled kind %v; extend policyFields", sf.Name, sf.Type.Kind())
34			}
35		}
36	
37		seenString := make(map[string]bool)
38		seenBool := make(map[string]bool)
39		for i := range policyFields {
40			f := &policyFields[i]
41			switch f.kind {
42			case policyFieldString, policyFieldOptionalString:
43				got := f.getString(p)
44				name, ok := lookupSentinel(got, sentinels)
45				if !ok {
46					t.Fatalf("field table entry %d reads %q, not any distinct struct field", i, got)
47				}
48				if seenString[name] {
49					t.Fatalf("Policy.%s is covered by more than one table entry", name)
50				}
51				seenString[name] = true
52			case policyFieldBool:
53				if !f.getBool(p) {
54					t.Fatalf("field table entry %d bool accessor does not read a stamped bool field", i)
55				}
56				matched := lookupBool(f, p)
57				if matched == "" {
58					t.Fatalf("field table entry %d bool accessor matches no struct field", i)
59				}
60				if seenBool[matched] {
61					t.Fatalf("Policy.%s bool is covered more than once", matched)
62				}
63				seenBool[matched] = true
64			default:
65				t.Fatalf("field table entry %d has unknown kind %d", i, f.kind)
66			}
67		}
68	
69		for name := range sentinels {
70			if !seenString[name] {
71				t.Fatalf("string Policy.%s is missing from policyFields", name)
72			}
73		}
74		for name := range boolFields {
75			if !seenBool[name] {
76				t.Fatalf("bool Policy.%s is missing from policyFields", name)
77			}
78		}
79	
80		// Setters must each write exactly one distinct field and round-trip with
81		// the matching getter, or archive decoding could populate the wrong
82		// member. Every other field must remain zero.
83		touchedString := make(map[string]bool)
84		touchedBool := make(map[string]bool)
85		for i := range policyFields {
86			f := &policyFields[i]
87			var q Policy
88			switch f.kind {
89			case policyFieldString, policyFieldOptionalString:
90				marker := fmt.Sprintf("\x01setter-%d\x01", i)
91				f.setString(&q, marker)
92				if f.getString(q) != marker {
93					t.Fatalf("entry %d setter/getter do not round-trip", i)
94				}
95				var hit string
96				qv := reflect.ValueOf(&q).Elem()
97				for j := 0; j < tp.NumField(); j++ {
98					if tp.Field(j).Type.Kind() != reflect.String {
99						continue
100					}
101					switch v := qv.Field(j).String(); v {
102					case marker:
103						hit = tp.Field(j).Name
104					case "":
105					default:
106						t.Fatalf("entry %d setter also wrote Policy.%s=%q", i, tp.Field(j).Name, v)
107					}
108				}
109				if hit == "" {
110					t.Fatalf("entry %d setter wrote no struct field", i)
111				}
112				if touchedString[hit] {
113					t.Fatalf("setter for Policy.%s used by two entries", hit)
114				}
115				touchedString[hit] = true
116			case policyFieldBool:
117				f.setBool(&q, true)
118				if !f.getBool(q) {
119					t.Fatalf("entry %d bool setter/getter do not round-trip", i)
120				}
121				var hit string
122				for j := 0; j < tp.NumField(); j++ {
123					if tp.Field(j).Type.Kind() != reflect.Bool {
124						continue
125					}
126					if reflect.ValueOf(&q).Elem().Field(j).Bool() {
127						hit = tp.Field(j).Name
128					}
129				}
130				if hit == "" {
131					t.Fatalf("entry %d bool setter wrote no struct field", i)
132				}
133				if touchedBool[hit] {
134					t.Fatalf("bool setter for Policy.%s used twice", hit)
135				}
136				touchedBool[hit] = true
137			}
138		}
139		for name := range sentinels {
140			if !touchedString[name] {
141				t.Fatalf("Policy.%s has no working string setter entry", name)
142			}
143		}
144		for name := range boolFields {
145			if !touchedBool[name] {
146				t.Fatalf("Policy.%s has no working bool setter entry", name)
147			}
148		}
149	
150		if len(policyFields) != tp.NumField() {
151			t.Fatalf("policyFields has %d entries, Policy has %d fields", len(policyFields), tp.NumField())
152		}
153	}
154	
155	func lookupSentinel(got string, sentinels map[string]string) (string, bool) {
156		for name, v := range sentinels {
157			if got == v {
158				return name, true
159			}
160		}
161		return "", false
162	}
163	
164	// lookupBool identifies the unique bool struct field whose value the spec
165	// reads; Policy has a single bool today, and the stamped value is true.
166	func lookupBool(f *policyFieldSpec, p Policy) string {
167		if !f.getBool(p) {
168			return ""
169		}
170		tp := reflect.TypeOf(Policy{})
171		for i := 0; i < tp.NumField(); i++ {
172			if tp.Field(i).Type.Kind() != reflect.Bool {
173				continue
174			}
175			probe := p // all bool fields stamped true
176			reflect.ValueOf(&probe).Elem().Field(i).SetBool(false)
177			if !f.getBool(probe) {
178				return tp.Field(i).Name
179			}
180		}
181		return ""
182	}
