		t.Fatal(err)
	}
	if _, err := s.Rollback(org, 2, 1); err != nil {
		t.Fatal(err)
	}
	s.Decide(org, reqs[0])

	records, cp, err := s.AuditExport(org, 0)
	if err != nil {
		t.Fatal(err)
	}
	for _, r := range records {
		fmt.Printf("REC %d %s %s\n", r.Seq, r.Kind, r.Fingerprint)
	}
	fmt.Printf("CP %d %s\n", cp.EndSeq, cp.Fingerprint)

	archive, err := EncodeAuditArchive(org, records, cp)
	if err != nil {
		t.Fatal(err)
	}
	sum := sha256.Sum256(archive)
	fmt.Printf("ARCHIVE %d %s\n", len(archive), hex.EncodeToString(sum[:]))

	// A hand-built chain forces the raw-byte fingerprint family through
	// fields the store path never produces (non-UTF8 org names, list
	// elements, reasons), including nil vs non-nil empty lists.
	rawOrg := "raw\xfforg"
	prev := genesisFingerprint(rawOrg)
	shapes := []*DecisionRecord{
		{Request: OrgRequest{SubjectOrg: rawOrg, ResourceOrg: rawOrg,
			Subject:  Subject{ID: "s\xff", Kind: "k\xfe", Roles: []string{"\xff"}, Disabled: true},
			Resource: Resource{ID: "r\xff", Scope: "sc\xfe"}, Action: "a\xff"},
			Decision: Decision{Allowed: true, Reason: "re\xff", Matched: []string{"m\xff", ""}, Version: 7}},
		{Request: OrgRequest{SubjectOrg: rawOrg, ResourceOrg: rawOrg,
			Subject:  Subject{Roles: nil},
			Resource: Resource{}, Action: ""},
			Decision: Decision{Matched: nil}},
		{Request: OrgRequest{SubjectOrg: rawOrg, ResourceOrg: rawOrg,
			Subject:  Subject{Roles: []string{}},
			Resource: Resource{}, Action: ""},
			Decision: Decision{Matched: []string{}}},
		{Request: OrgRequest{SubjectOrg: rawOrg, ResourceOrg: rawOrg,
			Subject:  Subject{Roles: []string{"", "\x00", " "}},
			Resource: Resource{ID: "\x00", Scope: " "}, Action: "\x00"},
			Decision: Decision{Allowed: true, Reason: "\x00\x01 ", Matched: []string{"", " "}, Version: 1}},
	}
	var rawRecords []AuditRecord
	for i, dr := range shapes {
		rec := &AuditRecord{Org: rawOrg, Seq: i + 1, Kind: AuditDecision,
			Decision: dr, PrevFingerprint: prev}
		rec.Fingerprint = fingerprintFor(rec)
		prev = rec.Fingerprint
		rawRecords = append(rawRecords, *rec)
		fmt.Printf("RAW %d %s\n", rec.Seq, rec.Fingerprint)
	}
	rawCp := Checkpoint{Org: rawOrg, EndSeq: len(rawRecords), Fingerprint: prev}
	rawArchive, err := EncodeAuditArchive(rawOrg, rawRecords, rawCp)
	if err != nil {
		t.Fatal(err)
	}
	rawSum := sha256.Sum256(rawArchive)
	fmt.Printf("RAWARCHIVE %d %s\n", len(rawArchive), hex.EncodeToString(rawSum[:]))

	// Mixed chain: policy change (nil and empty policy lists) alongside
	// decisions, in a valid-UTF8 org so JSON fingerprints are exercised.
	mixedOrg := "mixed"
	prev = genesisFingerprint(mixedOrg)
	var mixed []AuditRecord
	add := func(kind string, c *PolicyChange, d *DecisionRecord) {
		rec := &AuditRecord{Org: mixedOrg, Seq: len(mixed) + 1, Kind: kind,
			Change: c, Decision: d, PrevFingerprint: prev}
		rec.Fingerprint = fingerprintFor(rec)
		prev = rec.Fingerprint
		mixed = append(mixed, *rec)
	}
	add(AuditPolicyChange, &PolicyChange{Version: 1, Policies: nil}, nil)
	add(AuditPolicyChange, &PolicyChange{Version: 2, Policies: []Policy{}}, nil)
	add(AuditPolicyChange, &PolicyChange{Version: 3, Policies: []Policy{
		{ID: "p", Subject: "s", Action: "a", Scope: "sc", Effect: Allow, Recursive: true, ResourceID: "rid"},
	}, SourceVersion: 1, RolledBack: true}, nil)
	add(AuditDecision, nil, shapes[3])
	mixedCp := Checkpoint{Org: mixedOrg, EndSeq: len(mixed), Fingerprint: prev}
	for _, r := range mixed {
		fmt.Printf("MIX %d %s %s\n", r.Seq, r.Kind, r.Fingerprint)
	}
	mixedArchive, err := EncodeAuditArchive(mixedOrg, mixed, mixedCp)
	if err != nil {
		t.Fatal(err)
	}
	mixedSum := sha256.Sum256(mixedArchive)
	fmt.Printf("MIXARCHIVE %d %s\n", len(mixedArchive), hex.EncodeToString(mixedSum[:]))
}
